 mso 9]>          <v:background xmlns:v=\\"urn:schemas-microsoft-com:vml\\" fill=\\"t\\">            <v:fill type=\\"tile\\" color=\\"#eeeeee\\"></v:fill>          </v:background>        <![endif]-->          <span id=\\"__preview_text\\" style=\\"display:none;font-size:0;max-height:0;overflow:hidden\\">Cet envoi expire le mardi 20 oct. 2026 à 16h15</span>          <table width=\\"100%\\" cellspacing=\\"0\\" cellpadding=\\"0\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px\\">          <tr>            <td align=\\"center\\" valign=\\"top\\" style=\\"padding:0;margin:0\\">                <!-- ============================================ -->              <!-- HEADER : Logo + Titres -->              <!-- ============================================ -->              <table class=\\"es-header-body\\" width=\\"600\\" cellspacing=\\"0\\" cellpadding=\\"0\\" align=\\"center\\" bgcolor=\\"#ffffff\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px;background-color:#FFFFFF;width:600px\\">                <tr>                  <td align=\\"center\\" style=\\"padding:20px 10px 15px;margin:0;font-size:0px\\">                    <a id=\\"__a_logo\\" href=\\"https://www.grosfichiers.com/\\" target=\\"_blank\\" style=\\"-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;font-size:12px;text-decoration:underline;color:#CCCCCC\\">                      <img id=\\"__img_logo\\" class=\\"es-logo-light\\" src=\\"https://www.grosfichiers.com/img/grosfichiers_dark.png\\" alt=\\"Cliquez sur &#39;télécharger des images&#39; pour afficher les images\\" title=\\"GrosFichiers\\" width=\\"310\\" height=\\"45\\" style=\\"display:block;border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic;width:310px;height:45px;max-width:100%\\">                      <span class=\\"es-logo-dark-wrap\\" style=\\"display:none;mso-hide:all;max-height:0;overflow:hidden;font-size:0;line-height:0\\">                        <img id=\\"__img_logo_dark\\" class=\\"es-logo-dark\\" src=\\"https://www.grosfichiers.com/img/grosfichiers_light.png\\" alt=\\"Cliquez sur &#39;télécharger des images&#39; pour afficher les images\\" title=\\"GrosFichiers\\" width=\\"310\\" height=\\"45\\" style=\\"display:none;mso-hide:all;border:0;outline:none;text-decoration:none;-ms-interpolation-mode:bicubic;width:310px;height:45px;max-width:100%\\">                      </span>                    </a>                  </td>                </tr>                <tr id=\\"__title_1\\">                  <td align=\\"center\\" style=\\"padding:20px 10px 0;margin:0\\">                    <h2 style=\\"margin:0;line-height:30px;mso-line-height-rule:exactly;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;font-size:23px;font-style:normal;font-weight:normal;color:#333333\\">GARRIONE MATHILDE</h2>                  </td>                </tr>                <tr id=\\"__title_2\\">                  <td align=\\"center\\" style=\\"padding:0 10px;margin:0\\">                    <h2 class=\\"es-title-red\\" style=\\"margin:0;line-height:30px;mso-line-height-rule:exactly;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;font-size:23px;font-style:normal;font-weight:normal;color:#CC0000\\"><a style=\\"color:#CC0000;text-decoration:none;\\" href=\\"mailto:contact@mathildegarrione.com\\">contact@mathildegarrione.com</a></h2>                  </td>                </tr>                <tr id=\\"__title_3\\">                  <td align=\\"center\\" style=\\"padding:15px 10px 0;margin:0\\">                    <h2 style=\\"margin:0;line-height:30px;mso-line-height-rule:exactly;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;font-size:23px;font-style:normal;font-weight:normal;color:#333333\\">vous a envoyé un fichier</h2>                  </td>                </tr>              </table>                <!-- ============================================ -->              <!-- CONTENT : Lignes 1 à 3 -->              <!-- ============================================ -->              <table class=\\"es-content-body\\" width=\\"600\\" cellspacing=\\"0\\" cellpadding=\\"0\\" align=\\"center\\" bgcolor=\\"#ffffff\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px;background-color:#FFFFFF;width:600px\\">                <tr id=\\"__line_1\\">                  <td align=\\"center\\" style=\\"padding:40px 20px 0;margin:0\\">                    <p style=\\"margin:0;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:17px;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;line-height:25px;color:#333333\\">Disponible 14 jours (jusqu'au  mardi 20 oct. 2026 à 16h15)</p>                  </td>                </tr>                <tr>                  <td align=\\"center\\" height=\\"20\\" style=\\"padding:0;margin:0\\"></td>                </tr>                <tr id=\\"__line_2\\">                  <td align=\\"center\\" style=\\"padding:0 20px;margin:0\\"><div style=\\"font-size:1px;line-height:12px;height:12px\\">&nbsp;</div><table width=\\"100%\\" cellspacing=\\"0\\" cellpadding=\\"0\\" role=\\"presentation\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px\\"><tr><td style=\\"padding:12px 20px 10px;border-top:1px solid #AAAAAA;border-bottom:1px solid #AAAAAA;-webkit-text-size-adjust:none;-ms-text-size-adjust:none;mso-line-height-rule:exactly;font-size:14px;font-family:helvetica, 'helvetica neue', arial, verdana, sans-serif;line-height:21px;color:#333333;text-align:left\\">Bonjour Valentin,<br />\\n<br />\\nJe te transmet le fichier Sketchup d&#039;un projet d&#039;une construction neuve que je suis en train de faire avec un ami architecte sur Montélimar. Dans le fichier tu trouveras 3 scenes.<br />\\n<br />\\nLa premiere scene : Le pied de l&#039;ilot qui sera en bois (sur le sketchup il est en béton ciré mais les clients n&#039;en veulent plus) donc on partira sur un bois similaire à la cuisine. ON LAISSE TOMBER CELA ! LE CUISINISTE S&#039;EN CHARGE<br />\\n<br />\\nSeconde scene : le placard à peindre à côté de la porte d&#039;entrée qui cachera la gaine technique electrique, donc ne pas compter d&#039;étageres à l&#039;intérieur, seulement du push pour la porte (la porte ne doit pas toucher le sol comme sur la 3D pour que l&#039;aspirateur robot vienne se ranger à l&#039;intérieur), suivi d&#039;une banquette avec coussin d&#039;assise à tapisser qui continu en estrade et l&#039;element bibliothéque.<br />\\n<br />\\nTroisieme scene : Un grand meuble de rangement avec une partie cintrée (on ne vient pas faire de rangements dans la partie cintrée pareil que chez noblat), il y aura uniquement des étagères à l&#039;intérieur (j&#039;en ai compté 6 par caissons). + La tablette sous la tv suspendue afin de pouvoir poser decodeur,...<br />\\n<br />\\nEN PLUS : UN MEUBLE BOIS MEME FINITION QUE LE RESTE, AU DESSUS DU BATI SUPPORT DES WC COMME TU AVAIS FAIT CHEZ LES TAIEB STP LARGEUR 1M HAUTEUR 1M30.<br />\\n<br />\\nSi tu peux me faire un chiffrage pour cela je te remercie, le chantier a démarré et nous avons besoin d&#039;avoir les devis de tout rapidement. Le budget commence a être très serré donc je ne peux pas te proposer de t&#039;occuper des dressings et autres rangements de la maison, car nous passons par IKEA du coup. Pour te donner une idée de la teinte du bois choisi en façades chez IKEA c&#039;est la référenceTONSTAD Brun placage chêne teinte : https://www.ikea.com/fr/fr/p/tonstad-porte-brun-placage-chene-teinte-30510255/#content<br />\\nOn veut rester dans les même teintes pour l&#039;ensemble des meubles. Et on ira au plus avantageux niveau coût pour les matériaux.<br />\\n<br />\\nMerci d&#039;avance<br />\\nCordialement<br />\\n<br />\\nMathilde</td></tr></table><div style=\\"font-size:1px;line-height:20px;height:20px\\">&nbsp;</div></td>                </tr>                                                              </table>                <!-- ============================================ -->              <!-- BOUTON -->              <!-- ============================================ -->              <table id=\\"__button_1_table\\" class=\\"es-content-body\\" width=\\"600\\" cellspacing=\\"0\\" cellpadding=\\"0\\" align=\\"center\\" bgcolor=\\"#ffffff\\" style=\\"mso-table-lspace:0pt;mso-table-rspace:0pt;border-collapse:collapse;border-spacing:0px;background-color:#FFFFFF;width:600px\\">                <tr>                  <td id=\\"__button_1\\" align=\\"center\\" style=\\"padding:15px 20px 40px;margin:0\\"><!--[if mso]>  <v:roundrect xmlns:v=\\"urn:schemas-microsoft-com:vml\\" xmlns:w=\\"urn:schemas-microsoft-com:office:word\\" href=\\"https://www.grosfichiers.com/rVcP82wKaKj\\" style=\\"height:40px;v-text-anchor:middle;width:240px;\\" arcsize=\\"10%\\" stroke=\\"false\\" fillcolor=\\"#cc0000\\">  <w:anchorlock/>  <center style=\\"color:#ffffff;font-family:Helvetica,sans-serif;font-size:16px;\\">Téléchargez votre fichier</center>  </v:roundrect>  <![endif]-->    <a href=\\"https://www.grosfichiers.com/rVcP82wKaKj\\" target=\\"_blank\\" style=\\"mso-hide:all;display:inline-block;background-color:#CC0000;color:#FFFFFF;text-decoration:none;font-weight:normal;font-family:helvetica,'helvetica neue',arial,verdana,sans-serif;font-size:16px;padding:10px 25px;border-radius:5px;line-height:22px;\\">Téléchargez votre fichier</a>  </td>                </tr>              </table>                <!-- ============================================ -->              <!-- CONTENT : Lignes 4 à 5 -->              <!-- ============================================ -->              <table class=\\"es-content-body\\" width=\\"600\\" cellspacing=\\"0\\" cellpadding=\\"0\\" align=\\"center\\" bgcolor=\\"#ffffff\\" style=\\